SELECT purchase_date_utc, asin, marketplace_name, SUM(purchase_units_sold) AS purchase_units_sold, currency_code, SUM(unit_price * purchase_units_sold) AS revenue_purchased, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM amazon_retail_purchases GROUP BY purchase_date_utc, asin, marketplace_name, currency_code
